import pytest


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits (0 <= x <= 255, 0 <= k <= 7).

    Bits shifted out of the high end wrap around to the low end.
    The result is always in the range 0 to 255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


def test_zero_rotation_is_identity() -> None:
    for x in (0, 1, 127, 128, 255):
        assert rotl8(x, 0) == x


def test_simple_rotations() -> None:
    assert rotl8(1, 1) == 2
    assert rotl8(1, 7) == 128
    assert rotl8(0b01010101, 1) == 0b10101010


def test_wraparound() -> None:
    assert rotl8(0b10000001, 1) == 0b00000011
    assert rotl8(128, 1) == 1
    assert rotl8(0b10110001, 4) == 0b00011011
    assert rotl8(0b11000000, 2) == 0b00000011


def test_all_zeros_and_all_ones_fixed() -> None:
    for k in range(8):
        assert rotl8(0, k) == 0
        assert rotl8(255, k) == 255


def test_matches_reference_exhaustively() -> None:
    for x in range(256):
        for k in range(8):
            expected = ((x << k) | (x >> (8 - k))) & 0xFF
            assert rotl8(x, k) == expected


def test_result_in_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= 255


def test_inverse_rotation() -> None:
    for x in range(256):
        for k in range(8):
            assert rotl8(rotl8(x, k), (8 - k) % 8) == x


def test_composition() -> None:
    for x in (0, 1, 0x5A, 0x81, 0xB1, 255):
        for a in range(8):
            for b in range(8):
                assert rotl8(rotl8(x, a), b) == rotl8(x, (a + b) % 8)


def test_popcount_preserved() -> None:
    for x in range(256):
        for k in range(8):
            assert bin(rotl8(x, k)).count("1") == bin(x).count("1")


@pytest.mark.parametrize(
    ("x", "k", "expected"),
    [
        (0x01, 0, 0x01),
        (0x80, 7, 0x40),
        (0xF0, 4, 0x0F),
        (0x0F, 4, 0xF0),
        (0xA5, 3, 0x2D),
    ],
)
def test_parametrized(x: int, k: int, expected: int) -> None:
    assert rotl8(x, k) == expected
